				while ( false !== ($historyFileName = readdir ( $ipadDir )) ) {
					if ($historyFileName != "." && $historyFileName != "..") {
						$historyFilePath = $ipadDirPath . '/' . $historyFileName;
						$fh = fopen ( $historyFilePath, 'r' );
						if ($fh) {
							while ( ($line = fgets ( $fh )) !== false ) {
								$pregReturn = preg_match ( '/({"userid":".+]}).+classnameX/', $line, $matches );
								if ($pregReturn) {
									$jd = json_decode ( $matches [1] );
									foreach ( $jd->deliveryjson->invoice_list as $invoice ) {
										if (in_array ( $invoice->saleid, $missingInvoices )) {
											fwrite($jsonDataFile, $matches[1] . "\n");
											break;
										}
									}
								}
							}
							fclose ( $fh );
						} else {
							echo "    > Error opening file: $historyFilePath\n";
						}
					}
				}
				closedir ( $ipadDir );
			}
			fclose($jsonDataFile);
		}
